test('an owned assigned task stays UNSYNCED offline and changes only after an explicit original-key retry acknowledgement',async({page})=>{
 // Observe real UUID generation without replacing randomness or the transport.
 await page.addInitScript(()=>{const actual=crypto.randomUUID.bind(crypto),generated:string[]=[];(window as unknown as {__qaGeneratedCommandKeys:string[]}).__qaGeneratedCommandKeys=generated;crypto.randomUUID=()=>{const value=actual();generated.push(value);return value;};});
 await demo(page,'OWNER');const task=await command(page.request,'task.create',{siteId:'site-a',title:`QA offline owned task ${randomUUID()}`,unit:'UNIT',plannedQuantityMilli:1000,assigneeIds:['demo-employee'],billingScope:'INTERNAL'});expect(task.data.state).toBe('ASSIGNED');
 await demo(page,'EMPLOYEE');await navigate(page,'Tasks');await page.locator('#global-search').fill(task.data.title);await page.locator('.record-link').filter({hasText:task.data.title}).click();const t=translator('EN');await page.getByRole('dialog').locator('.detail-actions').getByRole('button',{name:`${t('start')} · ${t('tasks')}`,exact:true}).click();const dialog=page.getByRole('dialog');
 const taskStarts:unknown[]=[],retryReads:string[]=[];let observeRetry=false;page.on('request',request=>{const path=new URL(request.url()).pathname;if(observeRetry)retryReads.push(`${request.method()} ${path}`);if(path==='/api/v1/commands/task.start'&&request.method()==='POST')taskStarts.push(request.postDataJSON());});
 try{
  await page.context().setOffline(true);await expect(page.locator('.offline-strip')).toBeVisible();await dialog.getByRole('button',{name:'Review change',exact:true}).click();await expect(dialog).toContainText(`${t('version')} ${task.version}`);await dialog.getByRole('button',{name:'Keep as unsynced',exact:true}).click();await expect(dialog.getByRole('status').filter({hasText:'UNSYNCED'})).toContainText('UNSYNCED');await expect(dialog.locator('.success-state')).toHaveCount(0);
  const generatedBeforeRetry=await page.evaluate(()=>(window as unknown as {__qaGeneratedCommandKeys:string[]}).__qaGeneratedCommandKeys.slice());await dialog.getByRole('button',{name:'Close',exact:true}).click();const queued=page.getByRole('region',{name:'Unsent actions',exact:true}).locator('li');await expect(queued).toHaveAttribute('data-queue-state','UNSYNCED');expect(taskStarts).toEqual([]);
  const unchanged=(await (await page.request.get('/api/v1/entities/task')).json()).items.find((item:any)=>item.id===task.id);expect(unchanged).toMatchObject({version:task.version,data:{state:'ASSIGNED'}});
  await page.context().setOffline(false);await expect(page.locator('.offline-strip')).toHaveCount(0);await expect(queued.getByRole('button',{name:'Retry manually',exact:true})).toBeEnabled();await expect(queued).toHaveAttribute('data-queue-state','UNSYNCED');expect(taskStarts).toEqual([]);
  observeRetry=true;const retryResponse=page.waitForResponse(r=>r.url().endsWith('/api/v1/commands/task.start')&&r.request().method()==='POST');await queued.getByRole('button',{name:'Retry manually',exact:true}).click();const response=await retryResponse;expect(response.ok()).toBe(true);const acknowledged=await response.json();expect(acknowledged).toMatchObject({id:task.id,kind:'task',data:{state:'IN_PROGRESS'}});await expect(queued).toHaveAttribute('data-queue-state','ACKNOWLEDGED');expect(taskStarts).toHaveLength(1);
  const envelope=taskStarts[0] as {input:unknown;expected_version:number;idempotency_key:string};expect(envelope.input).toEqual({taskId:task.id});expect(envelope.expected_version).toBe(task.version);expect(generatedBeforeRetry).toContain(envelope.idempotency_key);const sentIndex=retryReads.indexOf('POST /api/v1/commands/task.start');for(const preflight of ['GET /api/v1/me','GET /api/v1/commands','GET /api/v1/entities/task']){expect(retryReads).toContain(preflight);expect(retryReads.indexOf(preflight)).toBeLessThan(sentIndex);}
  const persisted=(await (await page.request.get('/api/v1/entities/task')).json()).items.find((item:any)=>item.id===task.id);expect(persisted.version).toBe(acknowledged.version);expect(persisted.data.state).toBe('IN_PROGRESS');
 }finally{await page.context().setOffline(false);}
});

