 expect(commands.map((row:any)=>row.name)).toEqual(expect.arrayContaining(['automation_rule.create','automation_rule.preview','automation_rule.activate']));
 async function businessSnapshot(){const result:Record<string,{id:string;version:number}[]>={};for(const kind of ['decision','task','report','material_request','automation_run']){const response=await page.request.get(`/api/v1/entities/${kind}`);expect(response.ok(),`${kind}: ${await response.text()}`).toBe(true);result[kind]=(await response.json()).items.map((row:any)=>({id:row.id,version:row.version})).sort((a:any,b:any)=>a.id.localeCompare(b.id));}return result;}
